sys_variable_value.value:
(function execute(inputs, outputs) {

var name = inputs.nomeCompleto;

var parts = name.split(" ");
var first_name = parts[0];


var last_name = parts[parts.length - 1];

gs.info("Primeiro nome: " + first_name);
gs.info("Último nome: " + last_name);

outputs.primeironome = first_name;
outputs.ultimonome =  last_name;

})(inputs, outputs);

